// Synthetic demo records for preview mode.
//
// Generated by driving the real engine with a fake clock, so the coding of
// every field matches what a real session would produce. Every record is
// marked record_kind = "synthetic_demo" and stored only in the demo store.

import * as E from "./engine.js";

const LIKERT_IDS = ["risk_exposure", "risk_misuse", "risk_feel", "transp_explained", "transp_expect", "id_unexpected", "id_understood"];
const FOUR = ["yes", "no", "not_sure", "prefer_not"];

function pick(random, arr) {
  return arr[Math.floor(random() * arr.length)];
}

function fakeClock(random) {
  let t = 1_000_000;
  return {
    now: () => t,
    advance: (minMs, maxMs) => {
      t += Math.round(minMs + random() * (maxMs - minMs));
    },
  };
}

/**
 * Drive one synthetic session.
 *   pathway: one of the five final pathways
 *   condition: advance_notice | later_notice
 */
export function synthesizeRecord(config, { condition, pathway, random = Math.random, skipRate = 0.1 }) {
  const clock = fakeClock(random);
  const opts = () => ({ now: clock.now });
  const demoConfig = { ...config, mode: "preview", preview: { allowForcedCondition: true } };
  let s = E.createSession(opts());
  clock.advance(2000, 8000);
  E.begin(s, opts());
  clock.advance(3000, 12000);
  E.submitEligibility(s, demoConfig, { ageCategory: `age_${config.eligibility.minAge}`, meetsCriteria: true }, opts());
  clock.advance(8000, 40000);
  E.giveAssent(s, demoConfig, { ...opts(), forcedCondition: condition });
  s.recordKind = "synthetic_demo";
  clock.advance(2000, 10000);
  E.continueScenario(s, opts());
  E.confirmVerificationDisplayed(s);
  clock.advance(2500, 20000);

  const withdrawAt = pathway === "withdrawn" ? pick(random, ["verification", "result", "questionnaire"]) : null;
  if (withdrawAt === "verification") {
    E.withdraw(s, opts());
    return E.buildRecord(s, demoConfig);
  }

  if (pathway === "incomplete_session" && random() < 0.4) {
    // Ended before the initial decision.
    return E.buildRecord(s, demoConfig);
  }

  if (pathway === "declined_before_check") {
    E.initialDecision(s, E.INITIAL.DECLINE, opts());
  } else {
    E.initialDecision(s, E.INITIAL.START, opts());
    clock.advance(2990, 3040);
    E.simulationComplete(s, opts());
    clock.advance(2000, 25000);
    if (withdrawAt === "result") {
      E.withdraw(s, opts());
      return E.buildRecord(s, demoConfig);
    }
    if (pathway === "incomplete_session") {
      // Ended at the ID prompt without deciding.
      return E.buildRecord(s, demoConfig);
    }
    E.idDecision(s, pathway === "stopped_at_id_request" ? E.ID.STOP : E.ID.CONTINUE, opts());
  }
  clock.advance(1000, 4000);
  E.beginQuestionnaire(s, opts());
  clock.advance(30000, 180000);
  if (withdrawAt === "questionnaire") {
    E.withdraw(s, opts());
    return E.buildRecord(s, demoConfig);
  }

  // Synthetic answers. Slightly different distributions by condition so the
  // dashboard has something to show, with no claim about real effects.
  const answers = {};
  const reachedId = s.reachedResult;
  for (const id of LIKERT_IDS) {
    if ((id === "id_unexpected" || id === "id_understood") && !reachedId) continue;
    if (random() < skipRate) continue;
    let base = 3;
    if (id.startsWith("risk")) base = pathway === "would_continue_with_id" ? 2.6 : 3.8;
    if (id.startsWith("transp")) base = condition === "advance_notice" ? 3.9 : 2.9;
    if (id === "id_unexpected") base = condition === "advance_notice" ? 2.4 : 4.0;
    if (id === "id_understood") base = condition === "advance_notice" ? 4.0 : 2.2;
    const v = Math.min(5, Math.max(1, Math.round(base + (random() - 0.5) * 2.2)));
    answers[id] = String(v);
  }
  if (random() >= skipRate) {
    if (s.initialDecision === E.INITIAL.DECLINE) answers.recall_notice = pick(random, ["did_not_start", "yes", "no", "not_sure"]);
    else if (condition === "advance_notice") answers.recall_notice = pick(random, ["yes", "yes", "yes", "not_sure", "no"]);
    else answers.recall_notice = pick(random, ["no", "no", "no", "not_sure", "yes"]);
  }
  if (random() >= skipRate) answers.prior_experience = pick(random, FOUR);
  if (random() >= skipRate) answers.id_availability = pick(random, FOUR);
  if (random() >= skipRate) answers.breach_awareness = pick(random, FOUR);
  if (random() >= skipRate) {
    answers.open_influence = pick(random, [
      "Synthetic demo text: I did not want to share an ID for a voice chat.",
      "Synthetic demo text: the feature seemed worth it.",
      "Synthetic demo text: I was not expecting the ID request.",
      "Synthetic demo text: I knew it might happen so it was fine.",
    ]);
  }
  if (pathway === "declined_before_check" || pathway === "stopped_at_id_request") {
    if (random() >= skipRate) {
      const pool = ["privacy_security", "no_id_available", "too_much_effort", "unexpected_request", "feature_not_important", "other"];
      const n = 1 + Math.floor(random() * 3);
      const chosen = new Set();
      for (let i = 0; i < n; i += 1) chosen.add(pick(random, pool));
      answers.stop_reasons = [...chosen];
    }
  }
  if (config.demographics && config.demographics.enabled) {
    for (const item of config.demographics.items) {
      if (random() >= skipRate) answers[item.id] = pick(random, item.options).value;
    }
  }

  E.submitQuestionnaire(s, answers, opts());
  E.markSubmitted(s);
  return E.buildRecord(s, demoConfig);
}

/**
 * A demo data set that covers every condition and every pathway at least
 * once, then fills to `count` with weighted random pathways.
 */
export function generateDemoRecords(config, count = 40, random = Math.random) {
  const conditions = ["advance_notice", "later_notice"];
  const pathways = ["declined_before_check", "stopped_at_id_request", "would_continue_with_id", "incomplete_session", "withdrawn"];
  const weights = { declined_before_check: 0.2, stopped_at_id_request: 0.3, would_continue_with_id: 0.35, incomplete_session: 0.08, withdrawn: 0.07 };
  const records = [];
  for (const condition of conditions) {
    for (const pathway of pathways) {
      records.push(synthesizeRecord(config, { condition, pathway, random }));
    }
  }
  while (records.length < count) {
    const condition = pick(random, conditions);
    let r = random();
    let pathway = pathways[pathways.length - 1];
    for (const p of pathways) {
      if (r < weights[p]) {
        pathway = p;
        break;
      }
      r -= weights[p];
    }
    records.push(synthesizeRecord(config, { condition, pathway, random }));
  }
  return records;
}
